  if(a<=13)return [...dist,'Régional',NOLVL];
  if(a<=15)return [...dist,'Régional R2','Régional R1',NOLVL];
  if(a<=17)return [...dist,'Régional R2','Régional R1','National U17',NOLVL];
  if(a<=19)return [...dist,'Régional R2','Régional R1','National U19',NOLVL];
  if(/^Vétérans/.test(cat))return ['Loisir','District vétérans','Régional vétérans',NOLVL];
  if(cat==='Foot loisir')return ['Loisir',NOLVL];
