function layoutF(k){const rows=k.replace(/\s*\(.*\)/,'').split('-').map(Number).filter(n=>n>0);const R=rows.length;const out=[[50,88]];rows.forEach((n,i)=>{const y=R>1?Math.round(70-i*(54/(R-1))):40;const w=n===1?0:n===2?36:n===3?56:n===4?70:80;for(let j=0;j<n;j++)out.push([n===1?50:Math.round(50+w/2-j*w/(n-1)),y]);});return out;}
