// ---------- dates ----------
const T0=new Date();T0.setHours(0,0,0,0);
const iso=(d)=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const parse=(s)=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d);};
const addDays=(d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x;};
const TODAY=iso(T0);
const fdLong=(s)=>parse(s).toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});
const fdShort=(s)=>parse(s).toLocaleDateString('fr-FR',{weekday:'short',day:'numeric',month:'short'});
const cap=(s)=>s.charAt(0).toUpperCase()+s.slice(1);
const weekends=[];for(let i=1;i<=84;i++){const d=addDays(T0,i);if(d.getDay()===0||d.getDay()===6)weekends.push(iso(d));}
const sundays=weekends.filter(s=>parse(s).getDay()===0);
