load();
let toastMsg=null,toastTimer=null;
function toast(m){toastMsg=m;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toastMsg=null;const t=document.querySelector('.toast');if(t)t.remove();},2600);}

// ---------- getters ----------
const team=(tid)=>S.teams.find(t=>t.id===tid);
const club=(cid)=>S.clubs.find(c=>c.id===cid);
const clubOf=(tid)=>club(team(tid).club);
const tname=(tid)=>{const t=team(tid);const c=club(t.club);const n=S.teams.filter(x=>x.club===c.id).length;return n>1?c.name+' '+t.cat+(t.label?' '+t.label:''):c.name;};
const tshort=(tid)=>club(team(tid).club).name;
const tlabel=(tid)=>{const t=team(tid);if(!t||t.ext)return '';const n=S.teams.filter(x=>x.club===t.club&&!x.ext).length;return n>1?t.cat+(t.label?' '+t.label:''):'';};
let VILLES=[];try{fetch('villes.json').then(r=>r.ok?r.json():[]).then(a=>{if(Array.isArray(a)&&a.length){VILLES=a;}}).catch(()=>{});}catch(e){}
function villeFind(name){const n=norm(String(name||'').replace(/\s*\(\d+\)\s*$/,''));if(!n)return null;const t=Object.keys(TOWNS).find(k=>norm(k)===n);if(t)return [TOWNS[t][0],TOWNS[t][1]];const v=VILLES.find(x=>norm(x[0])===n);return v?[v[1],v[2]]:null;}
function villeSuggest(q){const n=norm(q);if(n.length<2)return [];const base=VILLES.length?VILLES:Object.keys(TOWNS).map(k=>[k,TOWNS[k][0],TOWNS[k][1],'91']);const a=base.filter(x=>norm(x[0]).startsWith(n));const b=a.length<8?base.filter(x=>!norm(x[0]).startsWith(n)&&norm(x[0]).includes(n)):[];return a.concat(b).sort((x,y)=>(y[3]==='91')-(x[3]==='91')||x[0].length-y[0].length).slice(0,8);}
function townPicker(name,dark,ph,val,opt){return `<label class="${dark?'f':'field'}">Ville<input name="${name}" data-townsearch autocomplete="off" ${opt?'':'required'} placeholder="${esc(ph||'Tape le nom de la ville')}" value="${esc(val||'')}"></label><input type="hidden" name="${name}_lat"><input type="hidden" name="${name}_lng"><div data-townres style="display:flex;flex-wrap:wrap;gap:6px;margin-top:-6px"></div><label class="${dark?'f':'field'}" data-exact style="display:none">Nom exact de ta commune (si elle n’est pas dans la liste)<input name="${name}_exact" placeholder="ex. Pecqueuse" autocomplete="off"></label>`;}
function townFromForm(fd,name){const raw=(fd.get(name)||'').trim();const picked=raw.replace(/\s*\(\d+[AB]?\)\s*$/,'');const exact=(fd.get(name+'_exact')||'').trim();const town=exact||picked;let lat=Number(fd.get(name+'_lat')),lng=Number(fd.get(name+'_lng'));if(!lat){const f=villeFind(picked)||villeFind(town);if(f){lat=f[0];lng=f[1];}}return {town,lat:lat||null,lng:lng||null,near:exact&&exact!==picked?picked:null};}
const pos=(cid)=>{const c=club(cid);if(c.lat&&c.lng)return [c.lat,c.lng];if(TOWNS[c.town])return TOWNS[c.town];const f=villeFind(c.town);if(f){c.lat=f[0];c.lng=f[1];return f;}return [48.6,2.2];};
const dist=(t1,t2)=>km(pos(team(t1).club),pos(team(t2).club));
const me=()=>team(S.me);
const myClub=()=>club(me().club);
function compatible(a,b){return !a.ext&&!b.ext&&a.id!==b.id&&a.club!==b.club&&a.acceptCats.includes(b.cat)&&b.acceptCats.includes(a.cat)&&a.acceptLvls.includes(b.lvl)&&b.acceptLvls.includes(a.lvl)&&a.fmts.some(f=>b.fmts.includes(f));}
const wa=(txt)=>'https://wa.me/?text='+encodeURIComponent(txt);
const waBtn=(txt,label,cls)=>`<a class="${cls||'lnk'}" href="${wa(txt)}" target="_blank" rel="noopener" style="display:inline-flex;align-items:center">${label||'Partager sur WhatsApp'}</a>`;
const goals=(pid)=>S.matches.reduce((n,m)=>n+((m.events||[]).filter(e=>e.player===pid&&(!e.type||e.type==='goal')&&!e.cancelled).length),0);
const fl=(t)=>t.fmts.map(f=>f==='Futsal (salle)'?'futsal':f.replace('Foot à ','à ')).join(', ');
const commonF=(a,b)=>a.fmts.filter(f=>b.fmts.includes(f));
const freeDays=(t)=>Object.keys(t.free).filter(d=>t.free[d]&&d>TODAY).sort();
function busy(tid,d){return S.matches.some(m=>(m.from===tid||m.to===tid)&&m.date===d&&(m.status==='accepted'));}
function candidates(){const a=me();return S.teams.filter(b=>compatible(a,b)).map(b=>{const d=dist(a.id,b.id);const common=freeDays(a).filter(x=>b.free[x]&&!busy(a.id,x)&&!busy(b.id,x));return {t:b,d,common};}).filter(x=>x.d<=a.radius&&x.d<=b2r(x.t)).sort((x,y)=>(y.common.length>0)-(x.common.length>0)||x.d-y.d);}
function b2r(t){return t.radius;}
const myMatches=()=>S.matches.filter(m=>m.from===S.me||m.to===S.me);
const other=(m)=>m.from===S.me?m.to:m.from;
const myConvs=()=>S.convs.filter(c=>(c.a===S.me||c.b===S.me)&&c.msgs.length).sort((x,y)=>last(y).at-last(x).at);
const last=(c)=>c.msgs[c.msgs.length-1]||{at:c.at||0,text:'Nouvelle conversation',from:null};
const unreadIn=(c)=>c.msgs.filter(m=>m.from!==S.me&&m.at>((c.seen||{})[S.me]||0)).length;
const unreadTotal=()=>myConvs().reduce((n,c)=>n+(unreadIn(c)>0?1:0),0);
function convWith(tid,create){let c=S.convs.find(c=>(c.a===S.me&&c.b===tid)||(c.b===S.me&&c.a===tid));if(!c&&create){c={id:id('v'),a:S.me,b:tid,seen:{},msgs:[]};S.convs.push(c);}return c;}

