  if(arts.length){const u=arts[0];h+=`<button data-a="readArt" data-id="${u.id}" style="all:unset;cursor:pointer;display:flex;flex-direction:column;gap:6px">${u.photo?`<img src="${u.photo}" alt="" decoding="async" style="width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:12px;background:#ECEAE4">`:''}${paperTag(u)}<span class="kicker">${u.pin?'📌 Épinglé · ':''}${artKicker(u)}</span><span class="hl" style="font-size:30px;line-height:1">${esc(u.title)}</span><span style="font-family:'Source Serif 4',serif;font-style:italic;font-size:16px;color:var(--mute)">${esc(u.chapo)}</span><span class="meta">Par ${esc(byName(u.by))} · ${esc(audTxt(u.aud,u))} · ${(u.bravo||[]).length} bravo${(u.bravo||[]).length>1?'s':''} · ${(()=>{const n=(S.comments||[]).filter(x=>x.art===u.id).length;return n+' commentaire'+(n>1?'s':'');})()}</span>${artCommPrev(u)}</button><button class="btn" data-a="readArt" data-id="${u.id}" style="background:var(--ink);color:#fff">Lire l’article →</button>`;
    if(arts.length>1)h+=`<div style="display:flex;flex-direction:column;gap:18px;border-top:2px solid var(--ink);padding-top:12px">${arts.slice(1,9).map(a=>`<button data-a="readArt" data-id="${a.id}" style="all:unset;cursor:pointer;display:flex;flex-direction:column;gap:6px;border-bottom:1px solid var(--line);padding-bottom:14px">${a.photo?`<img src="${a.photo}" alt="" loading="lazy" decoding="async" style="width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:12px;background:#ECEAE4">`:''}${paperTag(a)}<span class="kicker" style="font-size:11px">${a.pin?'📌 Épinglé · ':''}${artKicker(a)}</span><b style="font-family:Oswald,sans-serif;font-size:22px;line-height:1.05;text-transform:uppercase">${esc(a.title)}</b>${a.chapo?`<span style="font-family:'Source Serif 4',serif;font-style:italic;font-size:14px;color:var(--mute)">${esc(a.chapo)}</span>`:''}<span class="meta">Par ${esc(byName(a.by))} · ${(a.bravo||[]).length} bravo${(a.bravo||[]).length>1?'s':''} · ${(()=>{const n=(S.comments||[]).filter(x=>x.art===a.id).length;return n+' commentaire'+(n>1?'s':'');})()}</span>${artCommPrev(a)}<span style="align-self:flex-start;margin-top:4px;border:2px solid var(--ink);border-radius:10px;padding:8px 14px;font-family:Inter,sans-serif;font-size:14px;font-weight:700">Lire l’article →</span></button>`).join('')}</div>`;}
