  const pl=S.players.filter(p=>p.team===t.id);const wait=pl.filter(p=>p.rep==='wait').length;if(m&&wait)it(wait,`joueur${wait>1?'s n’ont':' n’a'} pas encore répondu pour le prochain match`,'go','club','squad');
  const sc=toFill(S.me).length;if(sc)it(sc,`score${sc>1?'s':''} à saisir`,'go','matchs','mine');
