  const hv=helpsFor(S.me).reduce((n,h)=>n+h.slots.reduce((k,x)=>k+Math.max(0,x.need-x.who.length),0),0);if(hv)it(hv,`poste${hv>1?'s':''} de bénévole${hv>1?'s':''} encore libre${hv>1?'s':''}`,'go','club','agenda');
