  const tv=all.reduce((n,p)=>n+verse(p),0),tr=all.reduce((n,p)=>n+reste(p),0);const cv=tv-nl*price,cr=tr-(all.length-nl)*price;rows[0][0]=pdfTxt('Licences (banque)');if(cols.length)rows.push([pdfTxt('TOTAL caisse en espèces (à part)'),'',cv+' EUR',cr+' EUR']);
  autoTable(doc,{startY:y2+3,margin:{left:12,right:12},head:[['',pdfTxt('Ont payé'),pdfTxt('Encaissé'),pdfTxt('Reste à encaisser')]],body:rows,styles:{font:'helvetica',fontSize:10,cellPadding:2.2,lineColor:[200,200,200],lineWidth:0.1},headStyles:{fillColor:[17,17,17],textColor:255,fontStyle:'bold'},columnStyles:{1:{halign:'center'},2:{halign:'right',fontStyle:'bold'},3:{halign:'right'}},didParseCell:(d)=>{if(d.section==='body'&&(d.row.index===0||(cols.length&&d.row.index===rows.length-1)))d.cell.styles.fontStyle='bold';}});
