  seaDel(d){S.seances=(S.seances||[]).filter(x=>x.id!==d.id&&x.own!==d.id);toast('Séance supprimée');},
  seaSend(d){if(!isCoach())return;const ups=upcomingTrainings(S.me,21);if(S.seaKey&&ups.some(u=>u.key===S.seaKey)){A.seaSendDo({id:d.id,k:S.seaKey});return;}if(!ups.length){A.seaSendDo({id:d.id,k:''});return;}S.modal={type:'seaSendTo',id:d.id};},
  seaSendDo(d){if(!isCoach())return;S.seances=S.seances||[];const own=S.seances.find(x=>x.id===d.id&&seaIsMine(x));const l=own?null:SEA_LIB.find(x=>x.id===d.id);if(!own&&!l)return;const key=d.k||'';
    S.seances=S.seances.filter(x=>!((x.lib||x.own)&&x.sentTo===S.me&&(x.forKey||'')===key));const r={id:id('se'),club:me().club,team:S.me,sentAt:Date.now(),sentTo:S.me,by:whoKey()};if(key)r.forKey=key;if(own)r.own=own.id;else r.lib=l.id;S.seances.push(r);
    const title=(own||l).title;const dt=key?fdLong(key.split('@')[1]):'';S.modal=null;S.seaKey=null;chatSys(S.me,'📋 Le coach a préparé la séance'+(dt?' du '+dt:'')+' : « '+title+' ». À voir sur ton accueil.');toast('Séance envoyée à l’équipe'+(dt?' pour le '+dt:''));},
  seaUnsend(d){const r=(S.seances||[]).find(x=>x.id===d.id);if(!r||!isCoach())return;if(r.lib||r.own)S.seances=S.seances.filter(x=>x.id!==r.id);else{delete r.sentTo;delete r.sentAt;delete r.forKey;}S.modal=null;toast('Séance retirée : les joueurs ne la voient plus');},
