  seaBSave(){const B=S.seaBuild;if(!B.items.length){toast('Ajoute au moins un bloc');return;}const title=(B.title||'').trim()||(B.key?'Séance du '+seaKeyLab(B.key):'Ma séance');let rid=B.edit;const v={title,pub:B.pub,dur:seaTot(B.items),blocks:B.items.map(it=>({b:it.b,dur:Number(it.dur)||0,v:it.v||''}))};S.seances=S.seances||[];if(B.edit){const x=S.seances.find(k=>k.id===B.edit);if(x){delete x.text;Object.assign(x,v);}}else{rid=id('se');S.seances.push(Object.assign({id:rid,club:me().club,team:S.me,by:whoKey(),at:Date.now()},v));}S.seaPub=B.pub;S.seaBuild=null;toast('Séance enregistrée');if(B.key&&rid)A.seaSendDo({id:rid,k:B.key});try{window.scrollTo(0,0);}catch(e){}},
