  fnPick(d){const dr=S.fnDraft;if(!dr)return;S.fnOpen=true;if(d.v==='admin'&&dr.crea)return;dr.f=dr.f.includes(d.v)?dr.f.filter(k=>k!==d.v):[...dr.f,d.v];Object.keys(dr.ov).forEach(a=>{if(dr.ov[a]===fnDefA(a,dr.f))delete dr.ov[a];});dr.sale=true;},
  fnTeam(d){const dr=S.fnDraft;if(!dr)return;S.fnOpen=true;dr.teams=dr.teams.includes(d.v)?dr.teams.filter(t=>t!==d.v):[...dr.teams,d.v];dr.sale=true;},
  accPick(d){const dr=S.fnDraft;if(!dr||!ACC.some(a=>a[0]===d.v))return;S.fnOpen=true;const on=Object.prototype.hasOwnProperty.call(dr.ov,d.v)?!!dr.ov[d.v]:fnDefA(d.v,dr.f);if(!on===fnDefA(d.v,dr.f))delete dr.ov[d.v];else dr.ov[d.v]=!on;dr.sale=true;},
  async fnSave(){const c=myClub();const dr=S.fnDraft;if(!dr||!can('admin',c.id))return 'keep';S.fnOpen=true;const u=dr.u;const mems=(CLOUD.clubMem||[]).filter(m=>m.user_id===u&&m.club_id===c.id&&m.statut==='actif');const cur=fnsOf(c.id,u,mems);const crea=mems.some(m=>m.role==='responsable');
    const nv=FNS.map(x=>x[0]).filter(k=>dr.f.includes(k));if(crea&&!nv.includes('admin'))nv.unshift('admin');const avantFn=(c.fn||{})[u];c.fn=Object.assign({},c.fn||{});c.fn[u]=nv.filter(k=>!(crea&&k==='admin'));c.fnPromo=Object.assign({},c.fnPromo||{});
    const staff=mems.find(m=>['responsable','coach','adjoint'].includes(m.role));const joueur=mems.find(m=>m.role==='joueur');let err=null;
    if(nv.length&&!staff&&joueur){const r=await sb.from('memberships').update({role:'adjoint'}).eq('id',joueur.id);err=r.error;if(!err){joueur.role='adjoint';c.fnPromo[u]=joueur.id;}}
    else if(!nv.length&&c.fnPromo[u]){const m=mems.find(x=>x.id===c.fnPromo[u]);if(m&&m.role==='adjoint'){const r=await sb.from('memberships').update({role:'joueur'}).eq('id',m.id);err=r.error;if(!err)m.role='joueur';}if(!err)delete c.fnPromo[u];}
    if(err){if(avantFn===undefined)delete c.fn[u];else c.fn[u]=avantFn;toast('Impossible d’enregistrer : '+err.message);save();render();return 'keep';}
    c.fnTeams=Object.assign({},c.fnTeams||{});if(fnBases(nv).some(b=>b==='coach'||b==='capitaine')&&dr.teams.length&&S.teams.filter(t=>t.club===c.id&&!t.ext).length>1)c.fnTeams[u]=dr.teams.slice();else delete c.fnTeams[u];
    c.acc=Object.assign({},c.acc||{});const ov={};if(nv.length&&!nv.includes('admin'))Object.keys(dr.ov).forEach(a=>{if(dr.ov[a]!==fnDefA(a,nv))ov[a]=!!dr.ov[a];});if(Object.keys(ov).length)c.acc[u]=ov;else delete c.acc[u];
    if(u!==CLOUD.uid){const noms=nv.map(fnNom).join(', ');const chg=cur.slice().sort().join()!==nv.slice().sort().join();const txt=!nv.length?'Tu n’as plus de fonction dans le club : tu restes joueur.':chg?'Tu es maintenant '+noms+'. Ouvre l’appli pour voir ton nouvel espace.':'Tes accès dans le club ont été mis à jour ('+noms+').';pushSend('user',u,c.name,txt,{club:c.id,url:'/?v=home'});}
    toast(nv.length?'Enregistré':'Enregistré : redevient simple joueur');S.fnDraft=null;
    if(u===CLOUD.uid){await cloudMembres();resolveIdentity();}save();render();return 'keep';},
  mFilter(d){S.mFilter=d.v;},
