  matchDelAsk(d){S.modal={type:'matchDel',id:d.id};},
  matchDel(d){const m=S.matches.find(x=>x.id===d.id);if(!m||!m.manual||!isCoach())return;if(m.status==='played'&&m.present)S.players.forEach(p=>{if(m.present.includes(p.id)&&p.mp)p.mp--;});S.matches=S.matches.filter(x=>x.id!==d.id);if(S.carpool)delete S.carpool[d.id];S.articles=(S.articles||[]).filter(a=>a.ref!=='compo:'+d.id);{const again=S.matches.some(x=>[x.from,x.to].includes(m.from)&&[x.from,x.to].includes(m.to));const ext=[m.from,m.to].map(team).filter(t=>t&&t.ext);purgeTalk(again?[]:ext.map(t=>(club(t.club)||{}).name),[m.from,m.to],[m.from,m.to].map(t=>(team(t)||{}).club),m.id);}S.modal=null;toast('Match supprimé');},
