  async resendMail(){const {error}=await sb.auth.resend({type:'signup',email:SU.mail,options:{emailRedirectTo:location.origin}});toast(error?AUTHERR(error.message):'Mail renvoyé');render();return 'keep';},
  async refreshMem(){await cloudMembres();if(CLOUD.mem.some(m=>m.statut==='actif'))await cloudLoadAll();resolveIdentity();render();return 'keep';},
  async memOk(d){const m=CLOUD.pending.find(x=>x.id===d.v);const sel=document.querySelector(`[data-assoc="${d.v}"]`);const ex=sel&&sel.value?S.players.find(x=>x.id===sel.value):null;const upd={statut:'actif'};
    if(m&&ex){const merge=(tmp)=>{if(!tmp)return;['birth','photo','pos','img'].forEach(k=>{if(tmp[k]!=null&&(ex[k]==null||ex[k]===''))ex[k]=tmp[k];});S.players=S.players.filter(x=>x.id!==tmp.id);};
      if(m.role==='joueur'){merge(S.players.find(x=>x.id===m.player_id));upd.player_id=ex.id;}
      else if(m.role==='parent'){const pa=(S.parents||[]).find(x=>x.id===m.player_id);if(pa){const old=pa.kids[0];merge(S.players.find(x=>x.id===old));pa.kids=pa.kids.map(k=>k===old?ex.id:k);}}}
    const {error}=await sb.from('memberships').update(upd).eq('id',d.v);if(!error&&m&&ex){save();CLOUD.clubMem.forEach(x=>{if(x.id===d.v)Object.assign(x,upd);});toast('Accès validé et relié à la fiche de '+ex.name);render();CLOUD.pending=CLOUD.pending.filter(x=>x.id!==d.v);return 'keep';}if(error){toast('Validation impossible : '+error.message);}else{if(m)m.statut='actif';CLOUD.pending=CLOUD.pending.filter(m=>m.id!==d.v);toast('Accès validé');}render();return 'keep';},
  async memNo(d){const m=CLOUD.pending.find(x=>x.id===d.v);const {error}=await sb.from('memberships').delete().eq('id',d.v);if(error){toast('Impossible : '+error.message);render();return 'keep';}
    CLOUD.pending=CLOUD.pending.filter(x=>x.id!==d.v);if(m&&m.player_id){S.players=S.players.filter(p=>p.id!==m.player_id||p.pre);S.parents=(S.parents||[]).filter(p=>p.id!==m.player_id);}toast('Demande refusée');save();render();return 'keep';},
  go(d){S.view=d.v;if(d.s){if(d.v==='matchs')S.sub.matchs=d.s;if(d.v==='club')S.sub.club=d.s;}else if(d.v==='club')S.sub.club='hub';S.openConv=null;if(d.v!=='tournois')S.openTour=null;try{window.scrollTo(0,0);}catch(e){}},
