  remindCol(d){const k=S.collectes.find(x=>x.id===d.id);const n=S.players.filter(p=>k.teams.includes(p.team)&&!(k.paid||{})[p.id]).length;k.teams.forEach(t=>chatSys(t,'Rappel : '+k.name+', '+k.amount+' € à régler avant le '+parse(k.due).toLocaleDateString('fr-FR',{day:'numeric',month:'long'})+(LIVE?'.':'. Paiement en ligne depuis « Moi ».')));notify(k.club,'Rappel : '+k.name+' ('+k.amount+' €) à régler');toast('Relance envoyée à '+n+' joueur'+(n>1?'s':''));},
  delCol(d){S.collectes=S.collectes.filter(x=>x.id!==d.id);},
  payCol(d){if(LIVE){toast('C’est le coach qui valide les paiements');return;}const k=S.collectes.find(x=>x.id===d.id);k.paid=k.paid||{};k.paid[d.p]={mode:'En ligne',at:Date.now()};const fee=Math.round((k.amount*0.025+0.25)*100)/100;toast('Payé '+k.amount+' € en ligne · frais '+fee.toFixed(2).replace('.',',')+' €');},
  vocal(){const tid=S.me;S.chats=S.chats||{};const sec=5+Math.floor(Math.random()*20);(S.chats[tid]=S.chats[tid]||[]).push({who:whoKey(),voice:'0:'+String(sec).padStart(2,'0'),at:Date.now()});toast('Démo : message vocal simulé. Dans l’appli, on maintient le micro pour enregistrer.');},
