  openLeague(d){S.openLeague=d.id;S.lsub='table';try{window.scrollTo(0,0);}catch(e){}},closeLeague(){S.openLeague=null;},
  lsub(d){S.lsub=d.v;},
  joinLeague(d){const L=S.leagues.find(x=>x.id===d.id);L.invited=L.invited.filter(x=>x!==S.me);if(d.v==='1'){L.teams.push(S.me);L.chat.push({who:'sys',text:tshort(S.me)+' a rejoint le championnat.',at:Date.now()});S.openLeague=L.id;toast('Tu as rejoint '+L.name);}else{L.chat.push({who:'sys',text:tshort(S.me)+' a décliné l’invitation.',at:Date.now()});toast('Invitation refusée');}},
  startLeague(d){const L=S.leagues.find(x=>x.id===d.id);if(L.teams.length<3){toast('Il faut au moins 3 équipes pour lancer le championnat');return;}let rounds=rr(L.teams);if(L.ar)rounds=rounds.concat(rounds.map(r=>r.map(([a,b])=>[b,a])));L.nR=rounds.length;
    rounds.forEach((pairs,k)=>{const dt=iso(addDays(parse(L.start),k*L.every));pairs.forEach(([a,b])=>S.matches.push({id:id('m'),from:a,to:b,date:dt,time:L.time,place:team(a).club,fmt:'Foot à 11',status:'accepted',league:L.id,round:k+1}));});
    L.started=true;L.invited=[];L.chat.push({who:'sys',text:'Championnat lancé : '+L.nR+' journées, du '+fdLong(L.start)+'. Bon championnat à tous !',at:Date.now()});L.teams.forEach(t=>{chatSys(t,'Le championnat '+L.name+' est lancé ! Calendrier dans Matchs → Championnat.');notify(team(t).club,'Championnat '+L.name+' : le calendrier est en ligne');});toast(L.nR+' journées créées, tous les clubs sont prévenus');},
  clearCompo(){const cp=S.compo[S.me];cp.slots=cp.slots.map(()=>'');},
  plus(){S.modal={type:'plus'};},
  plusDo(d){S.modal=null;const v=d.v;const isP=S.role==='player';if(v==='article'){openArticle('libre');return;}if(v==='help'){S.modal={type:'help'};return;}if(v==='propose'){S.modal={type:'ann'};return;}if(v==='manual'){S.modal={type:'manualMatch'};return;}if(v==='cal'){S.modal={type:'calOff'};return;}
    if(v==='propose'){S.view='matchs';S.sub.matchs='find';toast('Choisis l’équipe et touche « Proposer un match »');}
    else if(v==='player'){S.view='club';S.sub.club='squad';toast('Remplis le formulaire « Ajouter un joueur » en bas');}
    else if(v==='team'){S.modal={type:'team'};}
    else if(v==='training'){S.view='club';S.sub.club='agenda';toast('Formulaire « Ajouter un entraînement » plus bas');}
    else if(v==='event'){S.modal={type:'event'};}
    else if(v==='live'){const m=nextMatch();if(m)A.live({id:m.id});else toast('Pas de match confirmé à venir');}
    else if(v==='tour'){S.view='tournois';S.openTour=null;S.modal=newTourModal();}
    else if(v==='collect'){S.view='club';S.sub.club='caisse';toast('Formulaire « Nouvelle collecte » en bas');}
    else if(v==='league'){S.view='matchs';S.sub.matchs='champ';S.modal={type:'league',sel:[]};}
    else if(v==='photo'){if(isP){S.pview='club';}else{S.view='club';S.sub.club='photos';}toast('Remplis « Publier dans le club »');}
    else if(v==='vocal'){A.vocalGo();}
    else if(v==='injury'){A.myRep({v:'inj'});}
    else if(v==='score'){const x=toFill(S.me)[0];if(x)A.score({id:x.id});}},
