  nousDel(d){if(!isCoach())return;const tr=(S.trainings||[]).find(x=>x.id===d.id);if(!tr||!tr.label||!tr.date)return;const k=tr.id+'@'+tr.date;const etait=((S.trainState||{})[k])==='X';S.trainings=S.trainings.filter(x=>x.id!==tr.id);if(S.trainState)delete S.trainState[k];if(S.trainRsvp)delete S.trainRsvp[k];if(!etait&&tr.date>=TODAY)chatSys(tr.team,tr.label+' du '+fdLong(tr.date)+' annulé.');toast('Match supprimé');},
