  liveGoal(d){const m=S.matches.find(x=>x.id===S.modal.id);const mine=d.team===S.me||team(d.team).club===me().club;const e={type:'goal',team:d.team,player:null,assist:null,min:liveMin(m)};m.events.push(e);const sc=liveScore(m);
    const both=(t)=>{chatSys(m.from,t);chatSys(m.to,t);};[team(m.from).club,team(m.to).club].forEach(c=>notify(c,'But '+tshort(d.team)+' ('+e.min+'′) · '+tshort(m.from)+' '+sc[0]+'-'+sc[1]+' '+tshort(m.to)));if(mine)S.modal.pend=m.events.length-1;else both('But '+tshort(d.team)+' à la '+e.min+'′ · '+tshort(m.from)+' '+sc[0]+'-'+sc[1]+' '+tshort(m.to));toast('But '+tshort(d.team)+' à la '+e.min+'′ · '+sc.join('-'));},
  liveWho(d){const m=S.matches.find(x=>x.id===S.modal.id);const e=m.events[S.modal.pend];if(!e)return;if(d.k==='player'){e.player=d.id||null;if(!e.player){e.skip=true;A.liveWhoDone();}else if(e.pen){A.liveWhoDone();}}else{e.assist=d.id||null;A.liveWhoDone();}},
