  pnum(el){const p=S.players.find(x=>x.id===el.dataset.id);const n=Number(el.value)||null;if(n&&(n<1||n>99)){toast('Choisis un numéro entre 1 et 99');return;}const o=n&&S.players.find(x=>x.team===p.team&&x.id!==p.id&&x.num===n);if(o){toast('Le n° '+n+' est déjà pris par '+shortName(o.name)+'. Choisis-en un autre.');return;}p.num=n;toast(n?'N° '+n+' enregistré ✓':'Numéro retiré');}
